import { chromium } from 'playwright';
const BASE='https://www.statesideqm.com',THEME='158900125851',ROUTE='/collections/state-guard-series-vermont';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();p.setDefaultNavigationTimeout(70000);
let resp=null,error=null,attempt=0;
for(attempt=1;attempt<=4;attempt++){const u=new URL(ROUTE,BASE);u.searchParams.set('preview_theme_id',THEME);try{resp=await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});const s=resp?.status()||0;if(s===429||s===503){await sleep(attempt*12000);continue}await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await sleep(1400);break}catch(e){error=String(e?.message||e);if(attempt<4)await sleep(attempt*10000)}}
const theme=await p.evaluate(()=>({id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')})).catch(()=>({id:'',name:''}));
const trigger=p.locator('[data-sq-context-categories] [data-sq-rail-trigger]').first();let triggerVisible=false,categories=[],invalid=0;
try{triggerVisible=await trigger.isVisible();if(triggerVisible){await trigger.hover();await trigger.focus();await p.waitForTimeout(800)}categories=await p.locator('[data-sq-context-categories-list] a[href]').evaluateAll(as=>as.filter(a=>{const r=a.getBoundingClientRect(),s=getComputedStyle(a);return r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'}).map(a=>({label:(a.textContent||'').replace(/\s+/g,' ').trim(),href:a.href})));for(const x of categories){try{const u=new URL(x.href);if(u.origin!==new URL(BASE).origin||!/^\/collections\//.test(u.pathname))invalid++}catch{invalid++}}}catch(e){error=(error?error+' | ':'')+String(e?.message||e)}
const broken=await p.evaluate(()=>[...document.images].filter(i=>i.complete&&i.naturalWidth===0).length).catch(()=>0);
const row={http:resp?.status()??null,attempts:attempt,error,theme,previewOk:theme.id===THEME,triggerVisible,categoryCount:categories.length,invalidHrefs:invalid,brokenImages:broken,categories:categories.map(x=>x.label)};console.log('VERMONTSIDEBARRETRY',JSON.stringify(row));if(row.http!==200||!row.previewOk||error||!triggerVisible||!row.categoryCount||invalid||broken)process.exitCode=2;await c.close();await b.close();